displacement:
// Generiamo il frattale animato usando la tua funzione NoiseW!
// Parametri: x, y, z, ottave(4.0), lacunarità(2.0), gain(0.5)
float fractal = NoiseW(pModel.x * 2.0, pModel.y * 2.0 + t * 0.5, pModel.z * 2.0, 4.0, 2.0, 0.5);

// NoiseW restituisce valori da 0 a 1. Lo centriamo tra -0.5 e 0.5 e ne scaliamo la forza
float bump = (fractal - 0.5) * 0.15;

// Sottraiamo il rilievo dalla superficie
d_surf -= bump;

// TRUCCO DI SICUREZZA PER IL RAY MARCHING:
// Moltiplicando la distanza per 0.5 costringiamo i raggi a rallentare,
// impedendo che trapassino le punte del frattale diventando invisibili!
d_surf *= 0.5;
